mapper.select:
select ls.*,s.risknumber,o.orgname from TBL_RISK_IMPROVEMENT_DETAILS ls left join TBL_RISK_MONTHLY_EVALUATION nt on ls.IMPROVEMENT_ID = nt.id left join tbl_risk s on s.riskid=ls.riskid left join tbl_organization o on o.orgid=nt.unit_deptid where 1=1
and ls.BRANCH_ID=#{id}
and o.orgname LIKE concat(concat('%',#{orgname}),'%')
and ls.id in
#{item}
order by id desc

	select * from TBL_RISK_IMPROVEMENT_DETAILS
    where 1=1 

       and month=#{queryParam.month}


      and years=#{queryParam.years}


      and branch_id=#{queryParam.branchId}



    and  riskid=#{queryParam.riskid}
